from typing import List
from collections import defaultdict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        # quick impossibility check: max |alternating sum| is 12*n
        if abs(k) > 12 * n:
            return -1

        CAP = limit + 1  # sentinel for "product exceeded limit"

        # dp: (alternating_sum, parity_of_next_index) -> set of products (capped)
        dp = {}

        for i, x in enumerate(nums):
            rem = 12 * (n - 1 - i)  # max change to sum from remaining elements
            updates = []
            for (s, par), prods in dp.items():
                if par == 0:
                    ns = s + x
                else:
                    ns = s - x
                # prune states that can never reach sum k
                if abs(ns - k) > rem:
                    continue
                npar = 1 - par
                newset = set()
                for p in prods:
                    if x == 0 or p == 0:
                        np = 0
                    else:
                        if p == CAP:
                            np = CAP
                        else:
                            t = p * x
                            np = t if t <= limit else CAP
                    newset.add(np)
                updates.append(((ns, npar), newset))

            # start a new subsequence with just x (index 0, even -> next parity 1)
            if abs(x - k) <= rem:
                p0 = x if x <= limit else CAP
                updates.append(((x, 1), {p0}))

            for key, st in updates:
                if key in dp:
                    dp[key].update(st)
                else:
                    dp[key] = st

        ans = -1
        for par in (0, 1):
            st = dp.get((k, par))
            if st:
                for p in st:
                    if p <= limit and p > ans:
                        ans = p
        return ans

