from typing import List

class MedianCost:
    def __init__(self):
        self.low = []   # max-heap (negated)
        self.high = []  # min-heap
        self.low_size = 0
        self.high_size = 0
        self.low_sum = 0
        self.high_sum = 0
        self.delayed = defaultdict(int)

    def _prune_low(self):
        while self.low:
            v = -self.low[0]
            if self.delayed[v] > 0:
                self.delayed[v] -= 1
                heapq.heappop(self.low)
            else:
                break

    def _prune_high(self):
        while self.high:
            v = self.high[0]
            if self.delayed[v] > 0:
                self.delayed[v] -= 1
                heapq.heappop(self.high)
            else:
                break

    def _median(self):
        self._prune_low()
        return -self.low[0]

    def _rebalance(self):
        if self.low_size > self.high_size + 1:
            self._prune_low()
            v = -heapq.heappop(self.low)
            heapq.heappush(self.high, v)
            self.low_size -= 1
            self.low_sum -= v
            self.high_size += 1
            self.high_sum += v
        elif self.low_size < self.high_size:
            self._prune_high()
            v = heapq.heappop(self.high)
            heapq.heappush(self.low, -v)
            self.high_size -= 1
            self.high_sum -= v
            self.low_size += 1
            self.low_sum += v

    def add(self, v):
        if self.low_size == 0 or v <= self._median():
            heapq.heappush(self.low, -v)
            self.low_size += 1
            self.low_sum += v
        else:
            heapq.heappush(self.high, v)
            self.high_size += 1
            self.high_sum += v
        self._rebalance()

    def remove(self, v):
        m = self._median()
        if v <= m:
            self.low_size -= 1
            self.low_sum -= v
        else:
            self.high_size -= 1
            self.high_sum -= v
        self.delayed[v] += 1
        self._rebalance()
        self._prune_low()
        self._prune_high()

    def cost(self):
        m = self._median()
        return (m * self.low_size - self.low_sum) + (self.high_sum - m * self.high_size)


class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)
        num_windows = n - x + 1
        mc = MedianCost()
        costs = [0] * num_windows
        for i in range(x):
            mc.add(nums[i])
        costs[0] = mc.cost()
        for i in range(1, num_windows):
            mc.remove(nums[i - 1])
            mc.add(nums[i + x - 1])
            costs[i] = mc.cost()

        INF = float('inf')
        # dp[j][i]: min ops to place j subarrays within first i elements
        # dp[j][i] = min(dp[j][i-1], dp[j-1][i-x] + costs[i-x])
        prev = [0] * (n + 1)  # j = 0
        for j in range(1, k + 1):
            cur = [INF] * (n + 1)
            for i in range(1, n + 1):
                best = cur[i - 1]
                if i >= x:
                    cand = prev[i - x]
                    if cand < INF:
                        cand = cand + costs[i - x]
                        if cand < best:
                            best = cand
                cur[i] = best
            prev = cur
        return prev[n]

