            if f[a] != b:
                print(-1)
                return
        else:
            f[a] = b

    # If T uses all 26 letters and S != T, impossible
    if len(set(T)) == 26:
        print(-1)
        return

    k = sum(1 for c in f if f[c] != c)

    # count cycles in functional graph (edges c -> f[c] for c in f with f[c]!=c)
    state = {}  # 1 = in current path, 2 = done
    cycles = 0
    for start in f:
        if f[start] == start or state.get(start, 0) != 0:
            continue
        path = []
        c = start
        while c in f and f[c] != c and state.get(c, 0) == 0:
            state[c] = 1
            path.append(c)
            c = f[c]
        # check why we stopped
        if state.get(c, 0) == 1:
            # cycle found in current path
            cycles += 1
        for node in path:
            state[node] = 2

    print(k + cycles)

