        to[cnt] = u; nxt[cnt] = adj_head[v]; adj_head[v] = cnt; cnt += 1

    color = [-1]*(n+1)
    k = 0       # odd-size components
    sigma = 0   # isolated vertices (size-1 components)
    c11 = 0     # even components with both parts odd
    for s in range(1, n+1):
        if color[s] != -1:
            continue
        color[s] = 0
        q = deque([s])
        cnt0 = 0; cnt1 = 0
        while q:
            u = q.popleft()
            if color[u] == 0:
                cnt0 += 1
            else:
                cnt1 += 1
            e = adj_head[u]
            while e != -1:
                w = to[e]
                if color[w] == -1:
                    color[w] = color[u] ^ 1
                    q.append(w)
                e = nxt[e]
        size = cnt0 + cnt1
        if size % 2 == 1:
            k += 1
            if size == 1:
                sigma += 1
        else:
            if cnt0 % 2 == 1:  # both parts odd (sizes sum even, same parity)
                c11 += 1

    if n % 2 == 1:
        aoki = (m % 2 == 1)
    else:
        g = k - sigma
        if k == 0:
            aoki = ((c11 + m) % 2 == 1)
        elif g == 1 or g == 2:
            aoki = True
        elif g == 0:
            aoki = ((c11 + k//2 + m) % 2 == 1)
        else:
            aoki = (m % 2 == 1)

    print("Aoki" if aoki else "Takahashi")

