from collections import deque

def main():
    sys.setrecursionlimit(300000)
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1
    M = int(data[idx]); idx+=1
    K = int(data[idx]); idx+=1
    edges = []
    for _ in range(M):
        u = int(data[idx]); idx+=1
        v = int(data[idx]); idx+=1
        edges.append((u,v))

    class Dinic:
        def __init__(self,n):
            self.n=n; self.g=[[] for _ in range(n)]
        def add(self,u,v,c):
            self.g[u].append([v,c,len(self.g[v])])
            self.g[v].append([u,0,len(self.g[u])-1])
        def bfs(self,s,t):
            self.level=[-1]*self.n; self.level[s]=0
            q=deque([s])
            while q:
                u=q.popleft()
                for e in self.g[u]:
                    if e[1]>0 and self.level[e[0]]<0:
                        self.level[e[0]]=self.level[u]+1; q.append(e[0])
            return self.level[t]>=0
        def dfs(self,u,t,f):
            if u==t: return f
            while self.it[u]<len(self.g[u]):
                e=self.g[u][self.it[u]]
                v=e[0]
                if e[1]>0 and self.level[v]==self.level[u]+1:
                    d=self.dfs(v,t,min(f,e[1]))
                    if d>0:
                        e[1]-=d; self.g[v][e[2]][1]+=d; return d
                self.it[u]+=1
            return 0
        def flow(self,s,t,limit):
            fl=0
            while fl<limit and self.bfs(s,t):
                self.it=[0]*self.n
                while fl<limit:
                    f=self.dfs(s,t,limit-fl)
                    if f==0: break
                    fl+=f
            return fl

    Dmax = min(K, N-1)
    INF = K+1
    for D in range(Dmax, 0, -1):
        n = 2 + N*D
        S, T = 0, 1
        din = Dinic(n)
        def nid(v,i):
            return 2 + (v-1)*D + (i-1)
        # monotonicity: x_{v,i} >= x_{v,i+1}: forbid x_{v,i+1}=1 & x_{v,i}=0
        for v in range(1, N+1):
            for i in range(1, D):
                din.add(nid(v,i+1), nid(v,i), INF)
        # p_N = D : x_{N,D}=1
        din.add(S, nid(N,D), INF)
        # p_1 = 0 : x_{1,1}=0
        din.add(nid(1,1), T, INF)
        for (u,v) in edges:
            # cost 1 per level where x_{v,j}=1 and x_{u,j}=0 (counts p_v - p_u when positive)
            for j in range(1, D+1):
                din.add(nid(v,j), nid(u,j), 1)
            # forbid p_v >= p_u + 2: if x_{v,j+1}=1 and x_{u,j}=0 -> infinite
            for j in range(1, D):
                din.add(nid(v,j+1), nid(u,j), INF)
        f = din.flow(S, T, INF)
        if f <= K:
            print(D)
            return
    print(0)

