class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        s2 = str2.encode()
        ts = [i for i, c in enumerate(str1) if c == 'T']

        # Check consistency of overlapping T placements via Z-function of str2
        if ts and m > 1:
            z = [0] * m
            z[0] = m
            l = r = 0
            for i in range(1, m):
                zi = 0
                if i < r:
                    zi = min(r - i, z[i - l])
                while i + zi < m and str2[zi] == str2[i + zi]:
                    zi += 1
                z[i] = zi
                if i + zi > r:
                    l, r = i, i + zi
            for a, b in zip(ts, ts[1:]):
                d = b - a
                if d < m and z[d] != m - d:
                    return ""

        # Build word: forced chars from T placements, 'a' elsewhere
        word = bytearray(b'a' * L)
        forced = bytearray(L)
        upto = 0
        for t in ts:
            s = max(t, upto)
            e = t + m
            if s < e:
                word[s:e] = s2[s - t:]
                forced[s:e] = b'\x01' * (e - s)
                upto = e

        # Fix F windows greedily: flip rightmost free position to 'b'
        while True:
            changed = False
            for i in range(n):
                if str1[i] == 'F' and word[i:i + m] == s2:
                    jj = -1
                    for j in range(i + m - 1, i - 1, -1):
                        if not forced[j]:
                            jj = j
                            break
                    if jj < 0:
                        return ""
                    word[jj] = 98  # 'b'
                    forced[jj] = 1
                    changed = True
            if not changed:
                break

        return word.decode()

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = k + 1  # any count >= CAP is "enough"

        # capped factorials
        maxm = n + 1
        capfact = [1] * (maxm + 1)
        for i in range(1, maxm + 1):
            capfact[i] = min(capfact[i - 1] * i, CAP)

        odds = [i for i in range(1, n + 1) if i % 2 == 1]
        evens = [i for i in range(1, n + 1) if i % 2 == 0]

        def ways(o, e, next_parity):
            # number of alternating completions with o odds, e evens remaining,
            # next element must have parity next_parity (1 = odd, 0 = even)
            if o == 0 and e == 0:
                return 1
            if next_parity == 1:
                if not (o == e or o == e + 1):
                    return 0
            else:
                if not (e == o or e == o + 1):
                    return 0
            return min(capfact[o] * capfact[e], CAP)

        result = []
        required = None  # parity required for current position; None = any (first pos)

        for pos in range(n):
            if required is None:
                candidates = sorted(odds + evens)
            elif required == 1:
                candidates = list(odds)
            else:
                candidates = list(evens)

            placed = False
            for v in candidates:
                p = v % 2
                if p == 1:
                    o2, e2 = len(odds) - 1, len(evens)
                else:
                    o2, e2 = len(odds), len(evens) - 1
                nxt = 1 - p
                c = ways(o2, e2, nxt)
                if k > c:
                    k -= c
                else:
                    result.append(v)
                    if p == 1:
                        odds.remove(v)
                    else:
                        evens.remove(v)
                    required = 1 - p
                    placed = True
                    break
            if not placed:
                return []

        return result

