    def feasible(H):
        # intervals [max(0,H-D_i), min(U_i,H)], propagate with expansion X
        lo = 0
        hi = 0
        first = True
        for i in range(n):
            L = H - D[i]
            if L < 0:
                L = 0
            R = U[i] if U[i] < H else H
            if L > R:
                return False
            if first:
                lo, hi = L, R
                first = False
            else:
                lo -= x
                hi += x
                if L > lo:
                    lo = L
                if R < hi:
                    hi = R
                if lo > hi:
                    return False
        return True

    lo, hi = 0, hmax
    # find max feasible H; H=0 always feasible
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    print(S - n * lo)

