class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        # split p by the two '*'
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        a = p[:i1]
        b = p[i1 + 1:i2]
        c = p[i2 + 1:]
        n = len(s)

        def find_all(text, pat):
            # KMP: return sorted list of start indices of pat in text
            m = len(pat)
            if m == 0:
                return None
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k > 0 and pat[i] != pat[k]:
                    k = fail[k - 1]
                if pat[i] == pat[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i in range(len(text)):
                while k > 0 and text[i] != pat[k]:
                    k = fail[k - 1]
                if text[i] == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k - 1]
            return res

        lenA, lenB, lenC = len(a), len(b), len(c)
        occA = find_all(s, a) if a else None   # None means empty pattern (matches everywhere)
        occB = find_all(s, b) if b else None
        occC = find_all(s, c) if c else None

        if a and not occA:
            return -1
        if b and not occB:
            return -1
        if c and not occC:
            return -1

        # positions for b: if empty, all positions 0..n
        if occB is None:
            b_positions = range(n + 1)
        else:
            b_positions = occB

        INF = float('inf')
        ans = INF

        for j in b_positions:
            # find start i of a with i + lenA <= j, maximize i
            if occA is None:
                i = j  # empty a "ends" at j
            else:
                # largest start <= j - lenA
                limit = j - lenA
                idx = bisect.bisect_right(occA, limit) - 1
                if idx < 0:
                    continue
                i = occA[idx]
            # find start k of c with k >= j + lenB, minimize k
            start_c = j + lenB
            if occC is None:
                k = start_c
            else:
                idx = bisect.bisect_left(occC, start_c)
                if idx >= len(occC):
                    continue
                k = occC[idx]
            length = k + lenC - i
            if length < ans:
                ans = length

        return ans if ans != INF else -1

