class Solution:
    def countSubstrings(self, s: str) -> int:
        ans = 0
        cur3 = 0
        cur9 = 0
        c3 = [1, 0, 0]              # counts of prefix digit-sums mod 3 (includes empty prefix)
        c9 = [1, 0, 0, 0, 0, 0, 0, 0, 0]  # same mod 9
        need7 = '7' in s
        cnt7 = [0] * 7              # counts of substrings ending at prev pos, value mod 7
        n = len(s)
        prev_digit = 0
        for i in range(n):
            c = ord(s[i]) - 48
            cur3 = (cur3 + c) % 3
            cur9 = (cur9 + c) % 9

            if need7:
                new7 = [0] * 7
                for r in range(7):
                    v = cnt7[r]
                    if v:
                        new7[(r * 3 + c) % 7] += v  # 10 mod 7 == 3
                new7[c % 7] += 1
                cnt7 = new7

            if c == 1 or c == 2 or c == 5:
                ans += i + 1
            elif c == 3 or c == 6:
                # substrings ending at i with digit sum divisible by 3
                ans += c3[cur3]
            elif c == 9:
                ans += c9[cur9]
            elif c == 7:
                ans += cnt7[0]
            elif c == 4:
                ans += 1  # single digit "4"
                if i >= 1 and (prev_digit * 2 + c) % 4 == 0:  # 10 mod 4 == 2
                    ans += i  # all substrings of length >= 2 ending here
            elif c == 8:
                ans += 1  # single digit "8"
                if i >= 1:
                    if (prev_digit * 10 + 8) % 8 == 0:
                        ans += 1  # length-2 substring
                    if i >= 2:
                        last3 = (ord(s[i - 2]) - 48) * 100 + prev_digit * 10 + 8
                        if last3 % 8 == 0:
                            ans += i - 1  # all substrings of length >= 3

            c3[cur3] += 1
            c9[cur9] += 1
            prev_digit = c
        return ans

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def check(t: int) -> bool:
            # can we make min gameScore >= t with <= m moves?
            moves = 0
            pre = 0  # visits already granted to current index from previous oscillation
            for i in range(n):
                p = points[i]
                need = (t + p - 1) // p - pre
                if i == n - 1 and need <= 0:
                    # last index already covered, no need to step onto it
                    break
                # must step onto index i at least once to proceed
                if need < 1:
                    need = 1
                # 1 move to step in (gives 1 visit) + 2*(need-1) oscillation moves
                moves += 2 * need - 1
                if moves > m:
                    return False
                pre = need - 1  # oscillations pre-paid visits to next index
            return moves <= m

        lo = 0
        hi = (m // 2 + 1) * max(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

