    for c in S:
        h = (h * B + c) % MOD
        hs.append(h)
    ht = [0]; h = 0
    for c in T:
        h = (h * B + c) % MOD
        ht.append(h)
    L = max(n, m) + 1
    pw = [1] * L
    for i in range(1, L):
        pw[i] = pw[i - 1] * B % MOD

    def lcp(i, j):
        rem = n - i if n - i < m - j else m - j
        if rem <= 0 or S[i] != T[j]:
            return 0
        if (hs[i + rem] - hs[i] * pw[rem]) % MOD == (ht[j + rem] - ht[j] * pw[rem]) % MOD:
            return rem
        lo, hi = 1, rem - 1
        while lo < hi:
            mid = (lo + hi + 1) >> 1
            if (hs[i + mid] - hs[i] * pw[mid]) % MOD == (ht[j + mid] - ht[j] * pw[mid]) % MOD:
                lo = mid
            else:
                hi = mid - 1
        return lo

    size = 2 * K + 1
    NEG = -1
    fr = [NEG] * size
    fr[K] = lcp(0, 0)
    tgt = n - m + K
    if fr[tgt] >= n:
        print("Yes"); return

    for e in range(1, K + 1):
        new = [NEG] * size
        lo_k = -e if e < K else -K
