            best = NEG
            v = fr[idx]  # substitution
            if v >= 0:
                best = v + 1
            if idx > 0:
                v = fr[idx - 1]  # delete from S: i+1, diagonal k-1 -> k
                if v >= 0 and v + 1 > best:
                    best = v + 1
            if idx < size - 1:
