class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        # runs
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def feasible(L):
            if L == 1:
                # make alternating; cost = mismatches with 0101... or 1010...
                c = sum(1 for k in range(n) if (k % 2) != (s[k] == '1'))
                # pattern1: even index '0', odd '1' -> mismatch if s[k]=='1' at even or '0' at odd
                c1 = sum(1 for k in range(n) if int(s[k]) != k % 2)
                c2 = n - c1
                return min(c1, c2) <= numOps
            return sum(r // (L + 1) for r in runs) <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

