                    m = dp[1][1]
                if c >= f:
                    # target 0: key c, cost m + c
                    # target f: key c - f, cost m + c - f
                    ka, va = c, m + c
                    kb, vb = c - f, m + c - f
                    if ka == kb:
                        dp = [(ka, vb if vb < va else va)]
                    else:
                        dp = [(ka, va), (kb, vb)]
                else:
                    need = f - c
                    # target 0: key c, cost m + c
                    va = m + c
                    # target f: key 0, cost = prev_cost + need - min(S, need)
                    vb = None
                    for S, v in dp:
                        sav = S if S < need else need
                        cur = v + need - sav
                        if vb is None or cur < vb:
                            vb = cur
                    if c == 0:
                        dp = [(0, vb if vb < va else va)]
                    else:
                        dp = [(c, va), (0, vb)]
            best = dp[0][1]
            if len(dp) == 2 and dp[1][1] < best:
                best = dp[1][1]
            if best < ans:
                ans = best

        return ans

import sys
from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # owner[m] = index of some num that divides m (a multiple of that num)
        owner = [-1] * (threshold + 1)

        for i, x in enumerate(nums):
            if x > threshold:
                continue
            m = x
            while m <= threshold:
                if owner[m] == -1:
                    owner[m] = i
                else:
                    union(i, owner[m])
                m += x

        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
